import { test } from '@playwright/test';

import { loginAs } from '../bazis';

import { PRODUCT } from './product';

test('manager-places-a-task', async ({ page }) => {
  const app = await loginAs(page, PRODUCT, 'manager');
  await test.step('open: task-list', async () => {
    await app.open('task-list');
  });
  await test.step('action: create', async () => {
    await app.action('create');
  });
  await test.step('fill: {title: Inspect the site}', async () => {
    await app.fill({ title: 'Inspect the site' });
  });
  await test.step('submit', async () => {
    await app.submit({ saved: true });
    await app.expectScreen('task-card');
  });
  await test.step('expect: {screen: task-card, status: draft}', async () => {
    await app.expectScreen('task-card');
    await app.expectStatus('draft');
  });
  await test.step('fill: {location: 55.7558, 37.6173}', async () => {
    await app.action('edit');
    await app.fill({ location: '55.7558, 37.6173' });
  });
  await test.step('submit', async () => {
    await app.submit({ saved: true });
  });
  await test.step('expect: {values: {title: Inspect the site, location: 55.7558, 37.6173}}', async () => {
    await app.expectValues({ title: 'Inspect the site', location: '55.7558, 37.6173' });
  });
});
